select case when year(c.signup_date) < 2024 then 'before_2024' when year(c.signup_date) = 2024 then '2024' else 'after_2024' end as signup_cohort, sum(case when s.browser = 'Safari' then 1 else 0 end) as safari_count, sum(case when s.device = 'mobile' then 1 else 0 end) as mobile_count from sessions s left join customers c on s.customer_id = c.id group by case when year(c.signup_date) < 2024 then 'before_2024' when year(c.signup_date) = 2024 then '2024' else 'after_2024' end having safari_count >= 38 order by signup_cohort desc, mobile_count desc limit 1;
